// Integrity gate for the INGESTED news feed (roadmap item E).
//
// src/data/newsEntries.una.ts is AUTO-GENERATED by scripts/ingest/unaNews.cjs
// from Una's local `una-news/v1` feed and is published to the public site, so
// every row must be traceable:
//   · provenance  — which source produced it (never blank)
//   · verifiedAt  — ISO YYYY-MM-DD, copied from the source row (never today's date)
//   · url         — https:// only (Zero Trust: no http, no invented links)
//   · date        — ISO YYYY-MM-DD, and the whole array is newest-first
//   · topics      — non-empty, from the controlledUna vocabulary
//
// If this test fails, fix the SOURCE or the ingest script and re-run it —
// never hand-edit the generated module.

import { describe, it, expect } from 'vitest';

import {
  unaNewsItems,
  UNA_NEWS_GENERATED_AT,
  UNA_NEWS_WINDOW_DAYS,
  type NewsItem,
} from '../newsEntries.una';
import { newsItems, newsTopics, newsKinds } from '../newsFeed';

// Controlled vocabularies from ~/una/news_SCHEMA.md — the ingest drops
// anything outside these, so a value here is by definition unsourced.
const TOPICS = [
  'drug-discovery',
  'diagnostics-imaging',
  'oncology',
  'genomics',
  'health-data-ehr',
  'telemedicine',
  'trials',
  'policy-regulation',
  'funding',
  'model-release',
  'papers',
  'biosecurity',
];
const KINDS = [
  'funding',
  'launch',
  'model-release',
  'paper',
  'policy',
  'dataset',
  'acquisition',
  'partnership',
  'regulatory-clearance',
];
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

describe('ingested news feed integrity', () => {
  it('has at least one item', () => {
    expect(unaNewsItems.length).toBeGreaterThan(0);
  });

  it('carries a generatedAt stamp and a positive window', () => {
    expect(String(UNA_NEWS_GENERATED_AT)).toMatch(/^\d{4}-\d{2}-\d{2}/);
    expect(Number(UNA_NEWS_WINDOW_DAYS)).toBeGreaterThan(0);
  });

  it('every item carries provenance + a verifiedAt ISO date', () => {
    const bad = unaNewsItems.filter(
      (i) => !i.provenance || !ISO_DATE.test(i.verifiedAt ?? ''),
    );
    expect(bad.map((i) => i.id)).toEqual([]);
  });

  it('every item links out over https', () => {
    const bad = unaNewsItems.filter((i) => !/^https:\/\/\S+$/.test(i.url ?? ''));
    expect(bad.map((i) => `${i.id} ${i.url}`)).toEqual([]);
  });

  it('every item has an id, a title, a source, a date and a summary', () => {
    const bad: string[] = [];
    for (const i of unaNewsItems) {
      if (!i.id?.trim()) bad.push(`${i.title}: empty id`);
      if (!i.title?.trim()) bad.push(`${i.id}: empty title`);
      if (!i.source?.trim()) bad.push(`${i.id}: empty source`);
      if (!ISO_DATE.test(i.date ?? '')) bad.push(`${i.id}: bad date ${i.date}`);
      if (!i.summary?.trim()) bad.push(`${i.id}: empty summary`);
    }
    expect(bad).toEqual([]);
  });

  it('month-precision dates use the first of the month', () => {
    const bad = unaNewsItems
      .filter((i) => i.datePrecision === 'month' && !i.date.endsWith('-01'))
      .map((i) => i.id);
    expect(bad).toEqual([]);
  });

  it('every kind and topic comes from the controlled vocabulary', () => {
    const badKinds = unaNewsItems.filter((i) => !KINDS.includes(i.kind)).map((i) => i.id);
    const badTopics = unaNewsItems
      .filter((i) => !Array.isArray(i.topics) || i.topics.length === 0)
      .map((i) => i.id);
    const unknownTopics = unaNewsItems
      .flatMap((i) => i.topics.map((t) => ({ id: i.id, t })))
      .filter(({ t }) => !TOPICS.includes(t))
      .map(({ id, t }) => `${id}:${t}`);
    expect(badKinds).toEqual([]);
    expect(badTopics).toEqual([]);
    expect(unknownTopics).toEqual([]);
  });

  it('ids are unique', () => {
    const seen = new Set<string>();
    const dupes: string[] = [];
    for (const i of unaNewsItems) {
      if (seen.has(i.id)) dupes.push(i.id);
      seen.add(i.id);
    }
    expect(dupes).toEqual([]);
  });

  it('is sorted newest-first', () => {
    const dates = unaNewsItems.map((i: NewsItem) => i.date);
    const sorted = [...dates].sort((a, b) => b.localeCompare(a));
    expect(dates).toEqual(sorted);
  });

  // The UI reads the aggregated module; it must mirror the generated one.
  it('newsFeed exposes the same items, newest-first, with derived facets', () => {
    expect(newsItems.map((i) => i.id)).toEqual(unaNewsItems.map((i) => i.id));
    expect(newsTopics.length).toBeGreaterThan(0);
    expect(newsKinds.length).toBeGreaterThan(0);
    for (const t of newsTopics) expect(TOPICS).toContain(t);
    for (const k of newsKinds) expect(KINDS).toContain(k);
  });
});
